n("בת אור", "בת אור הוא שם עברי שבנוי מהמילים בת ואור, ופירושו בת של אור. השם שייך לקבוצה של שמות שמתחילים במילה בת, כמו בת שבע ובת ציון. השם ניתן לבנות, והוא נדיר. הוא נשמע בהיר ורך.", ["אור", "בתיה"])
n("אושן", "אושן היא המילה האנגלית לאוקיינוס. השם החדש הזה מביא תמונה של מרחב, של כחול ושל מים עמוקים. בארץ הוא נדיר מאוד, והוא ניתן גם לבנים וגם לבנות. קרובים אליו שמות עבריים כמו ים וימית.", ["ים", "ימית"])
n("אדלי", "אדלי היא צורה של אדל, שם שבא מגרמנית עתיקה ופירושו אצילה. באנגלית ובצרפתית השם נפוץ בשנים האחרונות. בארץ השם נדיר, והוא ניתן לבנות. קרובים אליו השמות אדל ואודליה.", ["אדל", "אודליה"])
n("אינה", "אינה הוא שם רוסי, ויש שרואים בו צורה קצרה של שמות כמו אנה וקרינה. השם היה נפוץ בברית המועצות, והוא הגיע לארץ עם העלייה. השם ניתן לבנות, והוא קצר ורך.", ["אנה"])
n("לריסה", "לריסה הוא שם רוסי ממקור יווני, ויש שקושרים אותו לעיר לריסה ביוון או למילה שחף. ברוסית השם נפוץ, וצורת החיבה שלו היא לארה. בארץ השם הגיע עם העלייה, והוא ניתן לבנות.", ["לארה"])
n("כרמלה", "כרמלה הוא שם עברי מהמילה כרמל, ההר שמעל חיפה, ובמקור כרם של עצי פרי. השם היה נפוץ בארץ בשנות הארבעים והחמישים. כרמלה ניתן לבנות, וקרובים אליו השמות כרמל וכרמית.", ["כרמל", "כרמית"])
n("הרצל", "הרצל הוא שם יידי מהמילה הרץ, לב, ופירושו לב קטן. בארץ השם נקרא לרוב על שם בנימין זאב הרצל, חוזה מדינת היהודים. השם ניתן לבנים, והוא היה נפוץ בשנים שאחרי קום המדינה. העיר הרצליה נקראה על שמו.", ["הרצליה"])
n("כוכבה", "כוכבה הוא שם עברי מהמילה כוכב, אור קטן בשמי הלילה. השם היה נפוץ בעיקר בקהילות של יהודי תימן ופרס, ובארץ בשנות הארבעים והחמישים. השם ניתן לבנות, וקרוב אליו השם כוכב.", ["כוכב"])
n("עופרה", "עופרה הוא שם עברי מהמילה עופר, צבי צעיר. השם היה נפוץ בארץ בשנות החמישים והשישים. הוא נשמע קליל ורך. עופרה היא גם שם של יישוב בבנימין. השם ניתן לבנות.", ["עפרה", "עופר"])
n("עוזי", "עוזי הוא שם עברי שפירושו העוז שלי, כוח וגבורה. מאותו שורש באים גם השמות עוז ועוזיאל. השם היה נפוץ בארץ בשנות הארבעים והחמישים. עוזי הוא גם שמו של תת המקלע הישראלי. השם ניתן לבנים.", ["עוז", "עוזיאל"])
n("ניצה", "ניצה הוא שם עברי מהמילה ניצה, ניצן של פרח שעוד לא נפתח. השם היה נפוץ בארץ בשנות הארבעים והחמישים. ניצה ניתן לבנות, והוא נשמע קצר ורך. קרובים אליו השמות ניצן וניצנה.", ["ניצן"])
n("דלית", "דלית היא ענף של גפן שמטפס על עמוד או על קיר. השם עברי, והוא היה נפוץ בארץ בשנות החמישים והשישים. דלית היא גם שם של קיבוץ. השם ניתן לבנות, וקרוב אליו השם דליה.", ["דליה"])
n("שגית", "שגית הוא שם עברי מהמילה שגיא, גדול ונעלה. השם היה נפוץ בארץ בשנות השבעים, והוא ניתן לבנות. הוא קצר ובהיר, וקרוב אליו השם שגיא, שניתן לבנים.", ["שגיא"])
n("דגנית", "דגנית הוא שם עברי מהמילה דגן, תבואה. השם מביא תמונה של שדות זהובים ושל קציר. הוא היה נפוץ בארץ בשנות החמישים והשישים, בתקופה של התיישבות חקלאית. השם ניתן לבנות.", ["דגן", "דגניה"])
n("נירה", "נירה הוא שם עברי מהמילה ניר, שדה חרוש ומוכן לזריעה. השם היה נפוץ בארץ בשנות הארבעים והחמישים, בתקופה של התיישבות חקלאית. נירה ניתן לבנות, וקרובים אליו השמות ניר ונירית.", ["ניר", "נירית"])
n("אידה", "אידה הוא שם בינלאומי ממקור גרמני, שפירושו כנראה עבודה או עוצמה. השם היה נפוץ בקהילות יהודיות באירופה, והוא מוכר בזכות האופרה אאידה. בארץ השם נדיר, והוא ניתן לבנות.", ["אדית"])
n("אוקסנה", "אוקסנה היא צורה אוקראינית של קסניה, שם יווני שקשור למילה קסניה, הכנסת אורחים. השם נפוץ באוקראינה וברוסיה. בארץ השם הגיע עם העלייה, והוא ניתן לבנות.", [])
n("שמרית", "שמרית הוא שם עברי מהשורש ש־מ־ר, שמירה. השם נשמע כמו ברכה שהילדה תהיה שמורה. הוא היה נפוץ בארץ בשנות השישים והשבעים, והוא ניתן לבנות. מאותו שורש באים גם השמות שמריה ושמריהו.", ["שמריהו"])
n("שולה", "שולה היא צורת חיבה של שולמית, השם שמופיע בשיר השירים. השם היה נפוץ מאוד בארץ בשנות הארבעים והחמישים. שולה ניתן לבנות, והוא נשמע חם ומשפחתי.", ["שולמית"])
n("פזית", "פזית הוא שם עברי מהמילה פז, זהב טהור. מאותה מילה באים גם השמות פז ואליפז. השם היה נפוץ בארץ בשנות השישים והשבעים, והוא ניתן לבנות.", ["פז"])
n("זויה", "זויה הוא שם רוסי שבא מהשם היווני זואי, חיים. ברוסית השם מוכר, והוא הגיע לארץ עם העלייה. בעברית השם נשמע קרוב לזיו ולזיוה. השם ניתן לבנות.", ["זואי", "זיוה"])
n("גיורא", "גיורא הוא שם ארמי שפירושו גר, מי שהצטרף לעם. השם היה נפוץ בארץ בשנות הארבעים והחמישים, גם בהשראת שמעון בר גיורא, ממנהיגי המרד הגדול ברומאים. השם ניתן לבנים.", ["גור"])
n("דורה", "דורה היא צורה קצרה של שמות כמו דורותיאה ותיאודורה, שמות יווניים שפירושם מתנה. השם היה נפוץ בקהילות יהודיות באירופה. בעברית הוא נשמע קרוב לדור ולדורית. השם ניתן לבנות.", ["דורית", "דור"])
n("אופירה", "אופירה הוא שם עברי מהמילה אופיר, ארץ רחוקה שממנה הביאו זהב. השם היה נפוץ בארץ בשנות החמישים והשישים. אופירה ניתן לבנות, וקרובים אליו השמות אופיר ואופרי.", ["אופיר", "אופרי"])
n("טניה", "טניה היא צורת חיבה רוסית של טטיאנה, שם לטיני עתיק. ברוסית השם נפוץ מאוד, והוא מוכר בזכות טטיאנה, הגיבורה של יבגני אונייגין. בארץ השם הגיע עם העלייה, והוא ניתן לבנות.", [])
n("סוזי", "סוזי היא צורת חיבה של סוזן, הצורה האירופית של שושנה, פרח השושן. השם היה נפוץ באנגלית ובצרפתית באמצע המאה העשרים. בארץ השם נדיר, והוא ניתן לבנות.", ["סוזן", "שושנה"])
n("ברברה", "ברברה הוא שם בינלאומי ממקור יווני, שפירושו זרה או מארץ רחוקה. השם היה נפוץ מאוד באירופה ובאמריקה באמצע המאה העשרים. בארץ השם נדיר, והוא ניתן לבנות.", [])
n("עדית", "עדית הוא שם עברי מהמילה עדי, תכשיט. מאותה מילה באים גם השמות עדי ועדיה. השם היה נפוץ בארץ בשנות השישים והשבעים, והוא ניתן לבנות. בשפות אחרות הוא נשמע גם כמו אדית.", ["עדי", "עדיה"])
n("אירנה", "אירנה הוא שם יווני שבא מהמילה אירנה, שלום. במיתולוגיה היוונית אירנה היא אלת השלום. השם נפוץ ברוסית ובפולנית, ובארץ הוא הגיע עם העלייה. השם ניתן לבנות.", ["אירינה"])
n("ורדית", "ורדית הוא שם עברי מהמילה ורד, הפרח הריחני. מאותה מילה באים גם השמות ורד וורדה. השם היה נפוץ בארץ בשנות השישים והשבעים, והוא ניתן לבנות.", ["ורד", "ורדה"])
n("אדית", "אדית הוא שם בינלאומי ממקור אנגלי עתיק, שבנוי מהמילים עושר ומלחמה. השם מוכר בזכות הזמרת אדית פיאף. בארץ הוא נשמע גם קרוב לעדית. השם ניתן לבנות, והוא נדיר.", ["עדית", "אידה"])
n("מוניק", "מוניק היא הצורה הצרפתית של מוניקה, שם ממקור לטיני. השם היה נפוץ בצרפת ובצפון אפריקה באמצע המאה העשרים, והוא הגיע לארץ עם העלייה. השם ניתן לבנות, והוא נדיר.", ["מוניקה"])
n("פטר", "פטר הוא שם שבא מהמילה היוונית פטרוס, סלע. השם נפוץ בגרמנית, בהונגרית ובשפות הסלאביות, ובאנגלית הוא פיטר. בארץ השם הגיע עם העלייה מאירופה, והוא ניתן לבנים.", ["פיטר"])
n("חנית", "חנית היא כלי נשק קדום, מקל ארוך עם להב בקצהו. השם עברי, והוא היה נפוץ בארץ בשנות החמישים והשישים. השם ניתן לבנות, וקרוב אליו השם חניתה. בצליל הוא קרוב גם לחנה ולחני.", ["חניתה", "חנה"])
n("אלברטו", "אלברטו היא צורה איטלקית וספרדית של אלברט, שם גרמני שפירושו אציל ומאיר. השם נפוץ באיטליה, בספרד ובאמריקה הלטינית. בארץ הוא נדיר, והוא ניתן לבנים.", [])
n("לואיס", "לואיס הוא שם בינלאומי ממקור גרמני, שפירושו לוחם מפורסם. בשפה הספרדית הוא נפוץ מאוד, ובצרפתית מוכרת הצורה לואי. בארץ השם נדיר, והוא ניתן לבנים.", [])
n("קלאודיה", "קלאודיה הוא שם לטיני, הצורה הנשית של קלאודיוס, שם של משפחה רומית עתיקה. השם נפוץ באיטלקית, בגרמנית ובשפה הספרדית. בארץ הוא נדיר, והוא ניתן לבנות.", [])
n("מריו", "מריו הוא שם איטלקי שבא מהשם הרומי מריוס, ויש שקושרים אותו למילה מאס, זכר. השם נפוץ באיטליה, בספרד ובאמריקה הלטינית. בארץ הוא נדיר, והוא ניתן לבנים.", [])
n("פאולה", "פאולה הוא הצורה הנשית של פאולוס, שם לטיני שפירושו קטן. השם נפוץ בשפה הספרדית, באיטלקית ובגרמנית. בארץ הוא נדיר, והוא ניתן לבנות. קרוב אליו השם פאולו.", ["פאולו"])
n("צפריר", "צפריר הוא שם עברי מהמילה צפריר, רוח קלה של בוקר. במסורת צפריר הוא גם שמו של מלאך של הבוקר. השם ניתן לבנים, והוא נדיר, אבל נשמע רענן ועדין.", [])
n("חבצלת", "חבצלת היא פרח לבן וריחני שפורח בסוף הקיץ על חולות החוף. בשיר השירים נאמר אני חבצלת השרון, שושנת העמקים. השם ניתן לבנות, והוא היה נפוץ בארץ בשנות הארבעים והחמישים.", [])
n("יוספה", "יוספה הוא הצורה הנשית של יוסף, שם עברי שפירושו אלוהים יוסיף. השם היה נפוץ בקהילות יהודיות באירופה ובארץ בדורות קודמים. השם ניתן לבנות, והוא נדיר היום.", ["יוסף"])
n("דרורה", "דרורה הוא שם עברי מהמילה דרור, חופש, וגם ציפור קטנה. השם היה נפוץ בארץ בשנות הארבעים והחמישים. דרורה ניתן לבנות, וקרובים אליו השמות דרור ודרורית.", ["דרור", "דרורית"])
n("יערית", "יערית הוא שם עברי מהמילה יער. מאותה מילה באים גם השמות יערה ויער. השם היה נפוץ בארץ בשנות השישים והשבעים, והוא ניתן לבנות. הוא מביא תמונה של עצים ושל צל.", ["יערה", "יער"])
n("ליליאנה", "ליליאנה הוא שם שבא מהמילה הלטינית ליליום, שושן צחור. השם נפוץ באיטלקית, ברומנית ובשפה הספרדית. בארץ הוא נדיר, והוא ניתן לבנות. מוכרת גם הצורה ליליאן.", ["ליליאן", "לילי"])
n("זמירה", "זמירה הוא שם עברי מהמילה זמר, שיר ומנגינה. מאותה מילה באים גם השמות זמיר וזמר. השם היה נפוץ בארץ בשנות הארבעים והחמישים, והוא ניתן לבנות.", ["זמיר"])
n("חמדה", "חמדה הוא שם עברי מהמילה חמדה, דבר יקר ונחמד. השם היה נפוץ בעיקר בקהילות של יהודי תימן, והוא ניתן לבנות. הוא נשמע חם ומשפחתי, ומביע אהבה לילדה.", [])
n("רוזליה", "רוזליה הוא שם שבא מהמילה רוזה, ורד. השם היה נפוץ באיטליה ובקהילות יהודיות במזרח אירופה, שם הוא קשור גם לשם רייזל. בארץ השם נדיר, והוא ניתן לבנות.", ["רייזל", "רוזה"])
n("אשרת", "אשרת הוא כתיב של אושרת, שם עברי מהמילה אושר. מאותו שורש באים גם השמות אשר ואושרי. השם ניתן לבנות, והכתיב הזה נדיר בארץ.", ["אושרת", "אושר"])
n("צביקה", "צביקה הוא צורת חיבה של צבי, שם עברי של בעל החיים הקל והמהיר. ביידיש השם היה בא לפעמים יחד עם הירש. צביקה היה נפוץ בארץ בשנות החמישים והשישים, והוא ניתן לבנים.", ["צבי"])
n("ארנה", "ארנה הוא שם עברי מהמילה אורן בכתיב חסר. השם קרוב לשמות אורנה ואורנית. ארנה ניתן לבנות, והוא היה מוכר בארץ בשנות החמישים. בשפות של אירופה הוא נשמע גם כמו ארנה, זירה.", ["אורנה", "אורן"])
